#!/usr/bin/env node
/**
 * Assemble the deployable site:
 *
 *   dist/
 *   ├─ index.html        ← landing page (../index.html, repo root)
 *   ├─ 404.html          ← landing page, so unknown URLs fall back to it
 *   ├─ photo.jpg         ← landing photo (../photo.jpg, repo root)
 *   ├─ CNAME             ← custom domain (generated by Hexo from source/CNAME)
 *   ├─ .nojekyll         ← keep GitHub Pages from running Jekyll
 *   ├─ hexo/             ← the whole Hexo blog, generated with root: /hexo/
 *   └─ ECLMA/            ← static society page (../ECLMA/site)
 *
 * Hexo itself lives in Hexo/ and is configured with url/root =
 * https://maywindsdu.cn/hexo and /hexo/, so every generated link already
 * carries the /hexo/ prefix. The main-site files stay at the repo root.
 */
import { execSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const hexoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const siteRoot = path.resolve(hexoRoot, '..');
const publicDir = path.resolve(hexoRoot, '..', 'dist');
const blogDir = path.join(publicDir, 'hexo');
const eclmaSite = path.join(siteRoot, 'ECLMA', 'site');
const eclmaDir = path.join(publicDir, 'ECLMA');

const hexoBin = path.join(
  hexoRoot,
  'node_modules',
  '.bin',
  process.platform === 'win32' ? 'hexo.cmd' : 'hexo'
);

function run(command) {
  execSync(command, { cwd: hexoRoot, stdio: 'inherit' });
}

function fail(message) {
  console.error(`\n[build-site] ${message}`);
  process.exit(1);
}

for (const required of [
  path.join(siteRoot, 'index.html'),
  path.join(siteRoot, 'photo.jpg'),
  path.join(hexoRoot, 'source', 'CNAME'),
  path.join(eclmaSite, 'index.html'),
  path.join(eclmaSite, 'style.css'),
  path.join(eclmaSite, 'assets', 'emblem.png'),
]) {
  if (!fs.existsSync(required)) fail(`missing ${required}`);
}

console.log('[build-site] hexo clean');
run(`"${hexoBin}" clean`);

console.log('[build-site] hexo generate');
run(`"${hexoBin}" generate`);

if (!fs.existsSync(path.join(publicDir, 'index.html'))) {
  fail('Hexo did not generate dist/index.html');
}

// Move the generated blog one level down into dist/hexo/.
fs.mkdirSync(blogDir, { recursive: true });
for (const entry of fs.readdirSync(publicDir)) {
  if (entry === 'hexo') continue;
  // CNAME must stay at the site root for GitHub Pages custom domains.
  if (entry === 'CNAME') continue;
  fs.renameSync(path.join(publicDir, entry), path.join(blogDir, entry));
}

// Landing page + its photo (shared by / and by the 404 fallback).
fs.copyFileSync(path.join(siteRoot, 'index.html'), path.join(publicDir, 'index.html'));
fs.copyFileSync(path.join(siteRoot, 'index.html'), path.join(publicDir, '404.html'));
fs.copyFileSync(path.join(siteRoot, 'photo.jpg'), path.join(publicDir, 'photo.jpg'));
fs.writeFileSync(path.join(publicDir, '.nojekyll'), '');

// Standalone ECLMA page, served at /ECLMA/.
fs.cpSync(eclmaSite, eclmaDir, { recursive: true });

for (const required of [
  'index.html',
  '404.html',
  'photo.jpg',
  'CNAME',
  'hexo/index.html',
  'ECLMA/index.html',
  'ECLMA/style.css',
  'ECLMA/assets/emblem.png',
]) {
  if (!fs.existsSync(path.join(publicDir, required))) fail(`missing dist/${required}`);
}

function sizeOf(dir) {
  let bytes = 0;
  let files = 0;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const sub = sizeOf(full);
      bytes += sub.bytes;
      files += sub.files;
    } else {
      bytes += fs.statSync(full).size;
      files += 1;
    }
  }
  return { bytes, files };
}

const total = sizeOf(publicDir);
const blog = sizeOf(blogDir);
console.log(
  `\n[build-site] done: ${total.files} files, ${(total.bytes / 1024 / 1024).toFixed(1)} MB total ` +
    `(blog: ${blog.files} files, ${(blog.bytes / 1024 / 1024).toFixed(1)} MB)`
);
console.log('[build-site] landing: /  ->  blog: /hexo/  ->  ECLMA: /ECLMA/');
